INSERT INTO topup_orders(order_id) SELECT NULL WHERE NOT(json_extract(?1,'$.now')>=json_extract(?1,'$.payment.checked_at') AND json_extract(?1,'$.now')<json_extract(?1,'$.payment.verification_deadline') AND json_extract(?1,'$.payment.verification_deadline')=json_extract(?1,'$.payment.checked_at')+60000 AND json_extract(?1,'$.now')>=json_extract(?1,'$.proof.checked_at') AND json_extract(?1,'$.now')<json_extract(?1,'$.proof.verification_deadline') AND json_extract(?1,'$.proof.verification_deadline')=json_extract(?1,'$.proof.checked_at')+60000 AND json_extract(?1,'$.proof.beneficiary_account_id')=json_extract(?1,'$.before.account_id') AND json_extract(?1,'$.proof.amount')=json_extract(?1,'$.before.coin_fen') AND json_extract(?1,'$.proof.remark')='topup:'||json_extract(?1,'$.before.order_id') AND json_extract(?1,'$.before.evm_tx_hash')=json_extract(?1,'$.payment.tx_hash') AND json_extract(?1,'$.before.evm_block_hash')=json_extract(?1,'$.payment.block_hash') AND json_extract(?1,'$.before.evm_block_number')=json_extract(?1,'$.payment.block_number') AND json_extract(?1,'$.before.evm_transaction_index')=json_extract(?1,'$.payment.transaction_index') AND json_extract(?1,'$.before.evm_log_index')=json_extract(?1,'$.payment.log_index') AND json_extract(?1,'$.before.evm_block_time_ms')=json_extract(?1,'$.payment.block_time_ms') AND json_extract(?1,'$.before.evm_actual_amount')=json_extract(?1,'$.payment.actual_amount'));
